def erl(s, extra=''): return '-module(lesson).\n-export([main/0]).\nmain() ->\n    '+s+'.\n'+extra

def objc(s): return '#import <Foundation/Foundation.h>\n#include <stdio.h>\nint main(void) {\n @autoreleasepool {\n'+s+'\n }\n return 0;\n}\n'
def asm(s, tail=''): return 'global _start\nsection .text\n_start:\n'+s+'\n    mov rax, 60\n    syscall\n'+tail

def cobol(declarations, steps): return 'identification division.\nprogram-id. lesson.\ndata division.\nworking-storage section.\n'+declarations+'\nprocedure division.\n'+steps+'\nstop run.\n'
course('haskell','Haskell','haskell','Examples use GHC 9.2 or later and the standard Prelude.','Install GHC. Save one example as lesson.hs and run runghc lesson.hs. Keep any definitions above main in the same file.','Haskell is a language built around functions. It encourages making new values instead of changing old ones.',[
L('first-message','Print a greeting','main is the starting action. putStrLn writes a line of text.','main = putStrLn "Hello, Asha!"','Hello, Asha!','Change the greeting.','Text uses double quotes; single quotes hold one character.'),
L('values','Name a value','A name can stand for a value. Haskell names do not work like boxes that are updated later.','pencils = 3\nmain = print (pencils + 2)','5','Use 6 pencils.','Give the name one definition in this scope.'),
L('functions','Name a calculation','Functions take inputs written after their name. This function doubles a number.','twice n = n * 2\nmain = print (twice 4)','8','Call twice 7.','Function calls use spaces, not a required pair of call parentheses.'),
L('types','Write a type guide','A type signature describes inputs and results. Int -> Int means a whole number in and out.','twice :: Int -> Int\ntwice n = n * 2\nmain = print (twice 4)','8','Try a decimal and read the type error.','The definition must agree with its type signature.'),
L('choices','Choose with if','An if expression always has then and else parts because it must produce a value.','message score = if score >= 5 then "Pass" else "Try again"\nmain = putStrLn (message 8)','Pass','Try message 3.','Both branches must produce the same kind of value.'),
L('lists','Read a short list','A list keeps values of one type in order. head reads the first item.','main = putStrLn (head ["cat", "dog"])','cat','Use a different nonempty list.','head fails on an empty list; pattern matching can handle that case.'),
L('map','Change every item','map applies a function to each list item and returns a new list.','main = print (map (* 2) [2, 3])','[4,6]','Multiply by 3 instead.','The original list is a value and is not changed in place.'),
L('filter','Keep matching items','filter keeps items that pass a true-or-false test.','main = print (filter (>= 7) [4, 8, 9])','[8,9]','Raise the limit to 9.','The test must return Bool, not a number.'),
L('patterns','Handle list shapes','Pattern matching selects steps based on a value shape. [] is an empty list; x:_ has a first item.','firstOrZero [] = 0\nfirstOrZero (x:_) = x\nmain = print (firstOrZero [8, 9])','8','Try the empty list.','Cover the empty-list case before assuming an item exists.'),
L('recursion','Repeat with a smaller job','A recursive function calls itself. This one stops at zero, then adds numbers on the way back.','sumTo n\n  | n <= 0 = 0\n  | otherwise = n + sumTo (n - 1)\nmain = print (sumTo 3)','6','Calculate sumTo 4.','A recursive function needs a case that stops.'),
L('maybe','Show that a value may be absent','Maybe holds Nothing or Just a value. Pattern matching handles both safely.','showScore Nothing = "No score"\nshowScore (Just n) = show n\nmain = putStrLn (showScore (Just 8))','8','Try showScore Nothing.','Handle both Nothing and Just cases.'),
L('comprehensions','Build a list from a rule','A list comprehension chooses inputs, filters them and builds new results.','main = print [n * 2 | n <- [1..4], n > 2]','[6,8]','Keep n > 1 instead.','Read the input and filter before working out the result.')])
course('elixir','Elixir','elixir','Examples use Elixir 1.14 or later on the Erlang runtime.','Install Elixir. Save each example as lesson.exs and run elixir lesson.exs.','Elixir is a language that runs on the Erlang runtime. It is used for apps that handle many small tasks.',[
L('first-message','Print a greeting','IO.puts writes text and adds a newline. IO means input and output.','IO.puts("Hello, Asha!")','Hello, Asha!','Change the name.','Keep quotes around strings.'),
L('values','Name a value','A name can be bound to a value. The plus sign adds numbers.','pencils = 3\nIO.puts(pencils + 2)','5','Use 6 pencils.','Values are not changed in place; a new binding is different from mutation.'),
L('atoms','Name a fixed label','An atom is a named label. It begins with a colon and is often used for a small set of choices.','status = :ready\nIO.inspect(status)',':ready','Try :waiting.','Do not create unlimited new atoms from user input.'),
L('tuples','Keep a small group','A tuple groups a few values. It is often used to return a status and a result together.','result = {:ok, 8}\nIO.puts(elem(result, 1))','8','Change the result to 6.','Tuple positions start at zero.'),
L('lists','Store a sequence','A list holds a sequence of values. Enum.join turns these strings into one string.','IO.puts(Enum.join(["cat", "dog"], ", "))','cat, dog','Add fish.','Lists and tuples are different data shapes.'),
L('maps','Use named fields','A map stores key-value pairs. Atom keys can be read with dot syntax.','book = %{title: "Moon Trip", pages: 24}\nIO.puts(book.title)','Moon Trip','Read book.pages.','A missing key with dot syntax raises an error.'),
L('matching','Pull values from a shape','The equals sign matches shapes and binds names to their parts.','{:ok, score} = {:ok, 8}\nIO.puts(score)','8','Use {:ok, 6}.','A shape that does not match raises a match error.'),
L('choices','Choose with if','if picks one of two branches. Only false and nil count as false in Elixir.','score = 8\nIO.puts(if score >= 5, do: "Pass", else: "Try again")','Pass','Try score 3.','Zero is a true value, so test a number with an explicit rule.'),
L('functions','Use an anonymous function','fn creates a function value. A dot is used when calling a function stored in a variable.','twice = fn n -> n * 2 end\nIO.puts(twice.(4))','8','Call twice.(7).','Do not omit the dot in this kind of function call.'),
L('map','Transform each value','Enum.map builds a list using the result of a function for each item.','values = Enum.map([2, 3], fn n -> n * 2 end)\nIO.puts(Enum.join(values, ", "))','4, 6','Multiply by 3.','Keep the returned list if you need it later.'),
L('pipes','Read steps from left to right','The pipe |> passes a value as the first input to the next function.','[4, 8, 9]\n|> Enum.filter(fn n -> n >= 7 end)\n|> Enum.sum()\n|> IO.puts()','17','Raise the limit to 9.','The piped value becomes the first argument, not the last.'),
L('case','Choose by a pattern','case matches a value against patterns. _ is a catch-all pattern.','result = {:ok, 8}\nmessage = case result do\n {:ok, n} -> "Score: #{n}"\n _ -> "Try again"\nend\nIO.puts(message)','Score: 8','Try result = :error.','Include a case for the shapes your program can receive.')])
course('erlang','Erlang','erlang','Examples use Erlang/OTP 25 or later.','Save each example as lesson.erl. Run erlc lesson.erl, then erl -noshell -s lesson main -s init stop. The file name must match the module name.','Erlang is a language built for many small tasks that send messages. It is used in reliable network systems.',[
L('first-message','Print a greeting','io:format writes output. ~n starts a new line. The module exports main so the command can call it.',erl('io:format("Hello, Asha!~n")'),'Hello, Asha!','Change the greeting.','The module name lesson must match lesson.erl.'),
L('variables','Bind one value','Variables start with a capital letter. A variable can be bound only once in a function call.',erl('Pencils = 3,\n    io:format("~p~n", [Pencils + 2])'),'5','Start with 6 pencils.','Matching a bound variable to a different value causes an error.'),
L('atoms','Use a named label','Atoms are fixed labels. An unquoted atom usually starts with a lower-case letter.',erl('Status = ready,\n    io:format("~p~n", [Status])'),'ready','Use waiting instead.','Names starting with capitals are variables, not atoms.'),
L('tuples','Group a few values','A tuple can hold a status and a result. Pattern matching pulls its parts into names.',erl('{ok, Score} = {ok, 8},\n    io:format("~p~n", [Score])'),'8','Change the number to 6.','The tuple shape and first atom must match.'),
L('lists','Split a list','[Head | Tail] separates the first item from the rest of a list.',erl('[First | _Rest] = [4, 5, 8],\n    io:format("~p~n", [First])'),'4','Change the first number.','An empty list cannot match a head-and-tail pattern.'),
L('maps','Read a named key','A map keeps key-value pairs. maps:get reads the value for a key.',erl('Book = #{title => "Moon Trip", pages => 24},\n    io:format("~s~n", [maps:get(title, Book)])'),'Moon Trip','Read pages using ~p.','A missing key needs a fallback or an explicit check.'),
L('case','Choose from patterns','case compares a value with patterns. The first matching branch supplies the result.',erl('Light = green,\n    Message = case Light of red -> "Stop"; green -> "Go"; _ -> "Wait" end,\n    io:format("~s~n", [Message])'),'Go','Try yellow.','Use semicolons between branches and end after the last branch.'),
L('guards','Check a number in a branch','A guard adds a small test after a pattern. when introduces that test.',erl('Score = 8,\n    Message = case Score of N when N >= 5 -> "Pass"; _ -> "Try again" end,\n    io:format("~s~n", [Message])'),'Pass','Try a score of 3.','Not every function is allowed inside a guard.'),
L('functions','Call a local function','A named function can take an input and return its final expression.',erl('io:format("~p~n", [twice(4)])','twice(N) -> N * 2.\n'),'8','Call twice(7).','End each function definition with a period.'),
L('comprehensions','Make a list by a rule','A list comprehension visits values and builds a result for each one.',erl('Doubled = [N * 2 || N <- [2, 3]],\n    io:format("~p~n", [Doubled])'),'[4,6]','Multiply each item by 3.','Use <- to take values from a list inside the comprehension.'),
L('send-receive','Send a message','A process has a mailbox. ! sends a message, and receive reads a matching message.',erl('self() ! {score, 8},\n    receive {score, N} -> io:format("~p~n", [N]) end'),'8','Send a different score.','receive waits if no message matches; real waiting code often needs after.'),
L('spawn','Start a small process','spawn starts a new process. It can send a result back to the parent process.',erl('Parent = self(),\n    spawn(fun() -> Parent ! {answer, 4 * 2} end),\n    receive {answer, N} -> io:format("~p~n", [N]) end'),'8','Send 7 * 2 instead.','Processes have their own data; share results with messages.')])
course('objective-c','Objective-C','objective-c','Examples use modern Objective-C with Apple Foundation and ARC on macOS.','On a Mac with Xcode command-line tools, save lesson.m. Run clang -fobjc-arc -framework Foundation lesson.m -o lesson, then ./lesson.','Objective-C adds objects and messages to C. You may meet it when reading older Apple app code.',[
L('first-message','Print a greeting','printf is a C printing function. This Objective-C file can still use ordinary C code.',objc('printf("Hello, Asha!\\n");'),'Hello, Asha!','Change the greeting.','Use a .m file so the compiler reads Objective-C.'),
L('numbers','Keep a whole number','An int stores a whole number. %d tells printf where to place it.',objc('int pencils = 3;\nprintf("%d\\n", pencils + 2);'),'5','Start with 6 pencils.','Match the print format to the number type.'),
L('strings','Use an NSString','NSString is an object holding text. The @ before the quotes makes an Objective-C string object.',objc('NSString *name = @"Asha";\nprintf("%s\\n", [name UTF8String]);'),'Asha','Use another name.','Plain "Asha" is C text, not an NSString object.'),
L('messages','Send a message to an object','Square brackets send a message. length asks a string for its length in UTF-16 units.',objc('NSString *word = @"cat";\nprintf("%lu\\n", (unsigned long)[word length]);'),'3','Try the simple English word books.','String length is not always the number of visible symbols.'),
L('formatting','Build a string with a value','stringWithFormat makes text with inserted values. %@ inserts an object description.',objc('NSString *name = @"Ravi";\nNSString *message = [NSString stringWithFormat:@"Hi, %@!", name];\nprintf("%s\\n", message.UTF8String);'),'Hi, Ravi!','Insert a different name.','Use %@ for Objective-C objects, not %s.'),
L('arrays','Read an array item','NSArray stores object values in order. The first index is zero.',objc('NSArray<NSString *> *pets = @[@"cat", @"dog"];\nprintf("%s\\n", pets[1].UTF8String);'),'dog','Read the first item.','Reading beyond the array count raises an exception.'),
L('dictionaries','Find a value by key','NSDictionary connects keys to values. A text key can describe the data.',objc('NSDictionary *book = @{@"title": @"Moon Trip", @"pages": @24};\nprintf("%s\\n", [book[@"title"] UTF8String]);'),'Moon Trip','Read pages and use intValue.','Numbers in object collections need boxing such as @24.'),
L('choices','Choose a message','Objective-C keeps C if statements. The comparison produces a true-or-false result.',objc('int score = 8;\nif (score >= 5) printf("Pass\\n"); else printf("Try again\\n");'),'Pass','Try score 3.','Use == for a numeric equality test, not assignment =.'),
L('loops','Visit each object','Fast enumeration visits each object in a collection using for-in.',objc('for (NSString *pet in @[@"cat", @"dog"]) { printf("%s\\n", pet.UTF8String); }'),'cat\ndog','Add fish.','Do not change the collection while enumerating it.'),
L('mutable-arrays','Add an object','NSMutableArray allows changes such as adding an object.',objc('NSMutableArray *scores = [NSMutableArray arrayWithArray:@[@4, @5]];\n[scores addObject:@8];\nprintf("%lu\\n", (unsigned long)scores.count);'),'3','Add @9 too.','NSArray is read-only; use a mutable collection for changes.'),
L('nil','Recognise no object','nil means no object. Checking it can select a fallback message.',objc('NSString *name = nil;\nprintf("%s\\n", name == nil ? "Guest" : name.UTF8String);'),'Guest','Give name @"Asha".','Do not add nil to an NSArray; it expects an object.'),
L('string-equality','Compare the text itself','isEqualToString compares string contents. Pointer equality asks whether two references point to one object.',objc('NSString *a = @"cat";\nNSString *b = [@"c" stringByAppendingString:@"at"];\nprintf("%s\\n", [a isEqualToString:b] ? "Same text" : "Different");'),'Same text','Change b to dog.','Use text equality when you care about the letters, not object identity.')])
course('assembly','Assembly','asm','Examples use NASM syntax for x86-64 Linux; they are not ARM or Windows assembly.','On x86-64 Linux, save lesson.asm. Run nasm -f elf64 lesson.asm -o lesson.o, then ld lesson.o -o lesson. Run ./lesson, then printf \'exit code: %s\\n\' "$?" immediately.','Assembly gives small instructions to a processor. These lessons use Linux exit codes to see simple results.',[
L('first-result','Return a small result','rdi is a register: a tiny storage place in the processor. Linux exit reads its status from rdi.',asm('    mov rdi, 5'),'exit code: 5','Change 5 to 7.','Exit codes are only 0 to 255; use small values in these lessons.'),
L('copy-register','Copy a register value','mov copies a value. It does not erase the source register.',asm('    mov rbx, 3\n    mov rdi, rbx'),'exit code: 3','Put 8 in rbx.','The destination comes first in NASM syntax.'),
L('addition','Add two numbers','add changes its first register by adding the second value.',asm('    mov rdi, 3\n    add rdi, 2'),'exit code: 5','Add 4 instead.','The add instruction changes the destination register.'),
L('subtraction','Subtract a number','sub subtracts the second value from the first register.',asm('    mov rdi, 8\n    sub rdi, 3'),'exit code: 5','Subtract 2 instead.','Keep the result within a small positive range for exit codes.'),
L('multiplication','Multiply a value','imul multiplies signed integers. This form stores the result in its first register.',asm('    mov rdi, 3\n    imul rdi, rdi, 2'),'exit code: 6','Multiply by 3.','Large results can overflow a register.'),
L('division','Divide a whole number','div divides rdx:rax by its input. For this small positive example, clear rdx first.',asm('    mov rax, 8\n    xor rdx, rdx\n    mov rbx, 3\n    div rbx\n    mov rdi, rax'),'exit code: 2','Try 9 divided by 3.','Never divide by zero. The remainder is in rdx, not rax.'),
L('bit-tests','Keep chosen bits','and keeps only bits that are 1 in both inputs. A final bit of 1 marks an odd number.',asm('    mov rdi, 5\n    and rdi, 1'),'exit code: 1','Try the even number 4.','Bitwise and is an operation on bits, not a high-level if statement.'),
L('branches','Choose a path','cmp compares values and sets flags. je jumps when the compared values are equal.',asm('    mov rdi, 0\n    mov rbx, 5\n    cmp rbx, 5\n    je .same\n    jmp .done\n.same:\n    mov rdi, 1\n.done:'),'exit code: 1','Compare rbx with 4.','A jump uses flags from the previous comparison; avoid changing them first.'),
L('loops','Repeat with a counter','A label names a place in the code. jnz repeats while the last result was not zero.',asm('    mov rcx, 3\n    mov rdi, 0\n.again:\n    add rdi, 2\n    dec rcx\n    jnz .again'),'exit code: 6','Start the counter at 4.','A loop needs a counter or rule that eventually stops.'),
L('stack','Save and restore a value','push places a value on the stack. pop takes the most recent value back.',asm('    push 7\n    pop rdi'),'exit code: 7','Push 4 instead.','Keep pushes and pops balanced.'),
L('calls','Call a small routine','call saves a return address and jumps. ret returns to the instruction after call.',asm('    mov rdi, 4\n    call twice','twice:\n    add rdi, rdi\n    ret\n'),'exit code: 8','Start with 3.','A routine reached by call should return with ret, not fall into unrelated code.'),
L('write-text','Ask Linux to write text','The write system call uses rax=1, rdi=1 for standard output, an address in rsi and a length in rdx.','global _start\nsection .data\nmessage: db "Hi", 10\nsection .text\n_start:\n    mov rax, 1\n    mov rdi, 1\n    lea rsi, [rel message]\n    mov rdx, 3\n    syscall\n    mov rdi, 0\n    mov rax, 60\n    syscall','Hi\nexit code: 0','Change Hi to Hey and change the length to 4.','The length counts bytes, including the newline byte.')])
course('cobol','COBOL','cobol','Examples use GnuCOBOL 3 in free-format mode.','Install GnuCOBOL. Save each example as lesson.cob, run cobc -x -free lesson.cob -o lesson, then run the program.','COBOL is a language often used in business systems. Its words describe data and steps in a detailed style.',[
L('first-message','Display a message','The procedure division holds steps. DISPLAY writes a value. STOP RUN ends the program.',cobol('', 'DISPLAY "Hello, Asha!"'),'Hello, Asha!','Change the name.','Compile these examples with -free because they use free-format source.'),
L('data-items','Name a number','Working-storage holds data. PIC 9 describes one decimal digit.',cobol('01 PENCILS PIC 9 VALUE 3.', 'DISPLAY PENCILS'),'3','Change the starting value to 6.','PIC 9 holds one digit; choose a wider picture for bigger numbers.'),
L('addition','Add to a count','ADD changes a numeric item by adding a value to it.',cobol('01 PENCILS PIC 9 VALUE 3.', 'ADD 2 TO PENCILS\nDISPLAY PENCILS'),'5','Add 4 instead.','Make sure the result fits the item picture.'),
L('compute','Work out a formula','COMPUTE assigns the result of a calculation.',cobol('01 ANSWER PIC 9.', 'COMPUTE ANSWER = 3 * 2\nDISPLAY ANSWER'),'6','Multiply 2 by 4.','A field that is too small can lose digits.'),
L('choices','Choose a message','IF checks a rule. END-IF marks where its branches finish.',cobol('01 SCORE PIC 9 VALUE 8.', 'IF SCORE >= 5\n DISPLAY "Pass"\nELSE\n DISPLAY "Try again"\nEND-IF'),'Pass','Try score 3.','End the conditional with END-IF before unrelated steps.'),
L('evaluate','Choose from several labels','EVALUATE selects steps by matching a value. WHEN OTHER is a fallback.',cobol('01 LIGHT PIC X VALUE "G".', 'EVALUATE LIGHT\n WHEN "R" DISPLAY "Stop"\n WHEN "G" DISPLAY "Go"\n WHEN OTHER DISPLAY "Wait"\nEND-EVALUATE'),'Go','Use R as the light value.','Use a picture large enough for each label.'),
L('loops','Repeat with a counter','PERFORM VARYING updates a counter and repeats until its stop rule is true.',cobol('01 N PIC 9.', 'PERFORM VARYING N FROM 1 BY 1 UNTIL N > 3\n DISPLAY N\nEND-PERFORM'),'1\n2\n3','Stop after 4.','Check that the counter changes toward the stopping rule.'),
L('tables','Read a table item','OCCURS makes repeated data items. Subscripts start at 1 in COBOL.',cobol('01 SCORES.\n 05 SCORE PIC 9 OCCURS 3 TIMES.', 'MOVE 4 TO SCORE(1)\nMOVE 5 TO SCORE(2)\nMOVE 8 TO SCORE(3)\nDISPLAY SCORE(2)'),'5','Read SCORE(3).','A table subscript must stay within its declared count.'),
L('text','Store a name','PIC X describes a character. A number in parentheses gives the field length.',cobol('01 STUDENT-NAME PIC X(4) VALUE "Asha".', 'DISPLAY STUDENT-NAME'),'Asha','Try the four-letter name Ravi.','Longer text needs a larger field or it will be cut short.'),
L('uppercase','Change text case','UPPER-CASE is a built-in function that makes letters uppercase.',cobol('', 'DISPLAY FUNCTION UPPER-CASE("asha")'),'ASHA','Try your name.','Call this with FUNCTION before the function name.'),
L('length','Measure a text field','LENGTH gives the declared length of this text field, including any spaces.',cobol('01 PET PIC X(3) VALUE "cat".\n01 SIZE-NUM PIC 9.', 'COMPUTE SIZE-NUM = FUNCTION LENGTH(PET)\nDISPLAY SIZE-NUM'),'3','Make PET four characters long.','Field length includes padding spaces; it is not always the typed word length.'),
L('paragraphs','Name a group of steps','A paragraph labels a group of steps. PERFORM runs that paragraph and returns.','identification division.\nprogram-id. lesson.\nprocedure division.\nPERFORM GREET\nSTOP RUN.\nGREET.\nDISPLAY "Hello again".','Hello again','Change the paragraph message.','STOP RUN before paragraph definitions prevents accidental fall-through at the end.')])
